// Turn the agent trace (result.steps) into "who called whom" lines
function tree(agent, steps, depth = 1, out = []) {
  for (const s of steps || []) {
    const pad = '  '.repeat(depth);
    if (s.step === 'agent') { out.push(`${pad}${agent} → agent ${s.to}.${s.action || ''}`); tree(s.to, s.sub_steps, depth + 1, out); }
    if (s.step === 'tool') out.push(`${pad}${agent} → tool ${s.to}.${s.action} (${s.ms} ms)`);
    if (s.step === 'llm_route' || s.step === 'llm_answer') out.push(`${pad}${agent} → LLM ${s.step} (${s.ms} ms)`);
    if (s.step === 'rule_route') out.push(`${pad}${agent} → rule → ${s.decision} (LLM skipped)`);
  }
  return out;
}

const calls = ['BO2 agent · Outfit of the day', 'BO2 agent · Change shoes', 'BO2 → BO1 · Forgotten pieces'];
return calls.map(n => {
  const r = $(n).first().json; const res = r.result || {};
  const steps = res.steps || [];
  const llm = JSON.stringify(steps).match(/"llm_(route|answer)"/g) || [];
  return { json: { button: n, handled_by: (res.data || {}).handled_by, llm_calls: llm.length,
                   who_called_whom: [`app → ${r.agent}`, ...tree(r.agent, steps)].join('\n') } };
});

// Turn the agent trace (result.steps) into "who called whom" lines
function tree(agent, steps, depth = 1, out = []) {
  for (const s of steps || []) {
    const pad = '  '.repeat(depth);
    if (s.step === 'agent') { out.push(`${pad}${agent} → agent ${s.to}.${s.action || ''}`); tree(s.to, s.sub_steps, depth + 1, out); }
    if (s.step === 'tool') out.push(`${pad}${agent} → tool ${s.to}.${s.action} (${s.ms} ms)`);
    if (s.step === 'llm_route' || s.step === 'llm_answer') out.push(`${pad}${agent} → LLM ${s.step} (${s.ms} ms)`);
    if (s.step === 'rule_route') out.push(`${pad}${agent} → rule → ${s.decision} (LLM skipped)`);
  }
  return out;
}

const r = $input.first().json; const res = r.result || {};
const steps = res.steps || [];
const llm = JSON.stringify(steps).match(/"llm_(route|answer)"/g) || [];
return [{ json: { sentence: 'What should I wear tomorrow for work?', reply: res.reply, llm_calls: llm.length,
                  model: res.model, who_called_whom: [`app → ${r.agent}`, ...tree(r.agent, steps)].join('\n') } }];
